<script>
(()=>{const select=document.getElementById('giftRate');if(!select)return;const art=document.getElementById('giftCardArt'),name=document.getElementById('giftCardName'),region=document.getElementById('giftCardRegion'),word=document.getElementById('giftCardWord'),icon=document.getElementById('giftCardIcon'),image=document.getElementById('giftCardImage');function render(){const o=select.selectedOptions[0];if(!o?.value){name.textContent='Choose a gift card';region.textContent='USA or UK · secure digital delivery';art.className='gcp-card-art';icon.className='bi bi-gift-fill';icon.hidden=false;word.hidden=false;if(image){image.hidden=true;image.removeAttribute('src')}word.textContent='GIFT CARD';return}const title=o.textContent.split(' · ')[0].trim(),lower=title.toLowerCase(),country=o.dataset.country==='US'?'United States':'United Kingdom',category=o.dataset.category||'';name.textContent=title;region.textContent=`${country} · ${o.dataset.currency||''} · secure digital delivery`;word.textContent=title.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,12)||'GIFT';art.className='gcp-card-art '+(lower.includes('apple')?'is-apple':lower.includes('amazon')?'is-amazon':category==='gaming'?'is-gaming':'is-retail');const hasImage=Boolean(o.dataset.image);if(image){image.hidden=!hasImage;if(hasImage)image.src=o.dataset.image}icon.hidden=hasImage;word.hidden=hasImage;icon.className=lower.includes('apple')?'bi bi-apple':category==='gaming'?'bi bi-controller':category==='streaming'?'bi bi-play-btn-fill':category==='prepaid'?'bi bi-credit-card-2-front-fill':'bi bi-bag-fill'}select.addEventListener('change',render);render()})();
</script>
<script>
(()=>{
 const format=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:2}).format(n);
 const currencyFormat=(n,c)=>new Intl.NumberFormat('en-US',{style:'currency',currency:c||'USD',maximumFractionDigits:2}).format(n);
 const c=document.getElementById('giftRate'),v=document.getElementById('faceValue'),d=document.getElementById('giftDenomination'),hint=document.getElementById('denominationHint'),u=document.getElementById('giftCurrency'),quoteCurrency=document.getElementById('giftQuoteCurrency');
 const orderCap={{ (float)$purchasePerOrderLimit }};const dailyRemaining={{ (float)$purchaseDailyRemaining }};
 const baseNgn=document.getElementById('giftBaseNgn'),usdValue=document.getElementById('giftUsdValue'),rateLabel=document.getElementById('giftRateUsd'),fee=document.getElementById('giftServiceFee'),totalDue=document.getElementById('giftTotalDue'),button=document.querySelector('#giftPurchaseForm button[type="submit"]');
 function syncDenominations(){const o=c?.selectedOptions[0],fixed=o?.dataset.fixedDenominations==='1',currency=o?.dataset.currency||'USD',unitRate=Number(o?.dataset.rate)||0,exchange=Number(o?.dataset.usdExchange)||1,markup=Number(o?.dataset.markup)||0;
  if(u)u.textContent=currency;if(quoteCurrency)quoteCurrency.textContent=currency;
  if(v){v.hidden=fixed;v.disabled=fixed;v.required=!fixed;if(fixed)v.removeAttribute('name');else v.name='face_value';}
  if(d){d.hidden=!fixed;d.disabled=!fixed;d.required=fixed;if(fixed)d.name='face_value';else d.removeAttribute('name');}
  if(hint)hint.hidden=!fixed;
  if(d&&fixed){const selected=d.value;Array.from(d.options).slice(1).forEach(opt=>{const value=Number(opt.value),base=value*unitRate;opt.textContent=`${currencyFormat(value,currency)} · ${format(base)}`;opt.disabled=base+markup>orderCap||base+markup>dailyRemaining;});if(Array.from(d.options).some(opt=>opt.value===selected&&!opt.disabled))d.value=selected;else d.value='';}
  f();
 }
 function f(){const o=c?.selectedOptions[0],r=Number(o?.dataset.rate)||0,x=Number(o?.dataset.usdExchange)||0,m=Number(o?.dataset.markup)||0,fixed=o?.dataset.fixedDenominations==='1',a=fixed?(Number(d?.value)||0):(Number(v?.value)||0),base=a*r,total=base+m,currency=o?.dataset.currency||'USD';
  if(usdValue)usdValue.textContent=currencyFormat(a*x,currency);if(baseNgn)baseNgn.textContent=format(base);
  if(rateLabel)rateLabel.textContent=x>0?`Rate: ₦${(r/x).toLocaleString('en-NG',{maximumFractionDigits:2})} / ${currency}`:'Rate: —';
